#!/usr/bin/python3
"""Reconcile invoice totals and payments using integer cents only."""

import csv
import os
import re
import tempfile

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CENT_RE = re.compile(r"^[+-]?[0-9]+$")


def cents(value):
    """Return an exact integer cent amount, rejecting non-canonical values."""
    if value is None or not CENT_RE.match(value):
        raise ValueError("malformed amount")
    return int(value, 10)


def publish(name, fieldnames, rows):
    """Atomically replace a generated CSV in the application directory."""
    handle = tempfile.NamedTemporaryFile(
        mode="w", newline="", encoding="utf-8", dir=BASE,
        prefix="." + name + ".", delete=False
    )
    try:
        with handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames, lineterminator="\n")
            writer.writeheader()
            writer.writerows(rows)
        os.replace(handle.name, os.path.join(BASE, name))
    except Exception:
        try:
            os.unlink(handle.name)
        except OSError:
            pass
        raise


def main():
    invoices = {}
    invoice_order = []
    rejected = []

    with open(os.path.join(BASE, "invoices.csv"), newline="", encoding="utf-8") as source:
        for line, row in enumerate(csv.DictReader(source), start=2):
            invoice_id = row.get("invoice_id", "")
            raw_total = row.get("total_cents", "")
            reasons = []
            if not invoice_id:
                reasons.append("missing invoice_id")
            elif invoice_id in invoices:
                reasons.append("duplicate invoice_id")
            try:
                total = cents(raw_total)
            except ValueError:
                total = None
                reasons.append("malformed total_cents")
            if reasons:
                rejected.append({
                    "source": "invoices.csv", "line": line,
                    "payment_id": "", "invoice_id": invoice_id,
                    "amount_cents": raw_total, "reason": "; ".join(reasons)
                })
                continue
            invoices[invoice_id] = total
            invoice_order.append(invoice_id)

    paid = dict((invoice_id, 0) for invoice_id in invoice_order)
    seen_payment_ids = set()
    with open(os.path.join(BASE, "payments.csv"), newline="", encoding="utf-8") as source:
        for line, row in enumerate(csv.DictReader(source), start=2):
            payment_id = row.get("payment_id", "")
            invoice_id = row.get("invoice_id", "")
            raw_amount = row.get("amount_cents", "")
            reasons = []
            if not payment_id:
                reasons.append("missing payment_id")
            elif payment_id in seen_payment_ids:
                reasons.append("duplicate payment_id")
            else:
                seen_payment_ids.add(payment_id)
            if invoice_id not in invoices:
                reasons.append("unknown invoice_id")
            try:
                amount = cents(raw_amount)
            except ValueError:
                amount = None
                reasons.append("malformed amount_cents")
            if reasons:
                rejected.append({
                    "source": "payments.csv", "line": line,
                    "payment_id": payment_id, "invoice_id": invoice_id,
                    "amount_cents": raw_amount, "reason": "; ".join(reasons)
                })
                continue
            paid[invoice_id] += amount

    balances = [
        {"invoice_id": invoice_id,
         "outstanding_cents": invoices[invoice_id] - paid[invoice_id]}
        for invoice_id in invoice_order
    ]
    publish("balances.csv", ["invoice_id", "outstanding_cents"], balances)
    publish(
        "rejected.csv",
        ["source", "line", "payment_id", "invoice_id", "amount_cents", "reason"],
        rejected,
    )


if __name__ == "__main__":
    main()
